(* [comment removed for export] *)
Local Ltac bge_klw RT LOWF LOW LOR KL :=
  lazymatch goal with A : ART RT ?S ?m0, MUx : munch _ ?m0 ?m1 |- _ =>
    assert (KL : keeps_live (rt_live RT S) m0 m1)
      by (let bb := fresh "bb" in let kk := fresh "kk" in let Hin := fresh "Hin" in let aa := fresh "aa" in let Haa := fresh "Haa" in
          let L1 := fresh "L" in let L2 := fresh "L" in let L3 := fresh "L" in
          intros bb kk Hin aa Haa; apply MUx;
          destruct (LOWF S m0 bb kk (bv_unsigned aa) A ltac:(repeat match goal with H : rt_frames _ _ = _ |- _ => rewrite H end; left; reflexivity) Hin Haa) as (L1 & L2 & L3);
          repeat match goal with H : rt_sp0 _ _ = _ |- _ => rewrite H in L3 end;
          cbn [outside]; clear - L1 L2 L3 LOW LOR; repeat split; try exact I; lia) end.
(* [comment removed for export] *)
Local Ltac bge_klc RT LOWF AG KL :=
  lazymatch type of AG with agree_on (fun a => aclient (rt_live RT ?S0) ?frs ?sp a /\ outside ?W a) ?m0 ?m1 =>
    lazymatch goal with A : ART RT ?S m0 |- _ =>
      assert (KL : keeps_live (rt_live RT S) m0 m1)
        by (let b := fresh "b" in let k := fresh "k" in let x := fresh "x" in let Hin := fresh "Hin" in let Hx := fresh "Hx" in
            let L1 := fresh "L" in let L2 := fresh "L" in let L3 := fresh "L" in
            apply (keeps_live_of_agree (rt_live RT S0) frs sp W m0 m1 (rt_live RT S) AG);
            [ intros b Hin; repeat match goal with H : rt_live _ _ = _ |- _ => rewrite H in * end; exact Hin
            | intros b k x Hin Hx;
              destruct (LOWF S m0 b k x A ltac:(repeat match goal with H : rt_frames _ _ = _ |- _ => rewrite H end; left; reflexivity) Hin Hx) as (L1 & L2 & L3);
              cbn [outside]; clear - L1; repeat split; try exact I; lia ]) end end.
(* [comment removed for export] *)
Local Ltac live_sub_tac ::=
  let e := fresh "e" in let He := fresh "He" in intros e He;
  try solve [destruct He];
  first [ match goal with S : forall x, In x ?l -> In x ?l' |- In _ ?l' => lazymatch type of He with In _ l => exact (S _ He) end end
        | repeat match goal with H : rt_live _ _ = _ |- _ => rewrite H in * end;
          repeat first [ exact He
                       | match goal with S : forall x, In x ?l -> In x ?l' |- In _ ?l' => lazymatch type of He with In _ l => exact (S _ He) end end
                       | apply in_or_app; right
                       | right
                       | apply live_remove_sub in He ] ].
(* [comment removed for export] *)
Local Ltac bge_uctx ra s0 ras m UCTX AGF RA4096 SPA usp A :=
  rewrite ?unsigned_lit by lia;
  lazymatch goal with FRx : rw_cells asegs ?mc A _ |- chain_ok ?mc _ _ _ =>
    let FRc := fresh "FRc" in let REC := fresh "REC" in
    pose proof FRx as FRc; split_before FRc (C8 s0) REC; clear FRc;
    replace (C8 s0) with (C8 (Z_to_bv 64 (bv_unsigned s0))) in REC by (rewrite Z_to_bv_bv_unsigned; reflexivity);
    replace (C8 ra) with (C8 (Z_to_bv 64 (bv_unsigned ra))) in REC by (rewrite Z_to_bv_bv_unsigned; reflexivity);
    apply (chain_ok_push mc _ usp (bv_unsigned ra) (bv_unsigned s0) ras);
    [ lia | clear - SPA; Z.div_mod_to_equations; lia | unfold USTACK_TOP; lia | exact RA4096 | apply bv_unsigned_in_range
    | exact REC
    | apply (chain_ok_keep ras m mc usp (bv_unsigned s0) UCTX); eapply agree_sub; [exact AGF|];
      let x := fresh "x" in let Hx := fresh "Hx" in intros x Hx; cbv beta; split; [left; exact Hx| cbn [outside]; exact I] ] end.
