        by (let b := fresh "b" in let k := fresh "k" in let x := fresh "x" in let Hin := fresh "Hin" in let Hx := fresh "Hx" in
            let L1 := fresh "L" in let L2 := fresh "L" in let L3 := fresh "L" in
            apply (keeps_live_of_agree (rt_live RT S0) frs sp W m0 m1 (rt_live RT S0) AG);
            [ intros b Hin; exact Hin
            | intros b k x Hin Hx;
              destruct (LOWF S0 mm b k x A ltac:(repeat match goal with H : rt_frames _ _ = _ |- _ => rewrite H end; left; reflexivity) Hin Hx) as (L1 & L2 & L3);
              cbn [outside]; clear - L1; repeat split; try exact I; lia ]) end end.


